steps.action:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "query { users(limit: 100) { nodes { id name email organization { name } } } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "query { users(first: 100) { nodes { id name email organization { name } } } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "query { issues(first: 100, filter: { assignee: { id: { eq: \"u-priya_guest\" } } }) { nodes { id identifier title name priority assignee { name } } } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "query { issues(first: 100, filter: { assignee: { id: { eq: \"u-priya_guest\" } } }) { nodes { id identifier title priority } } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "mutation { issueUpdate(id: \"i-sec-payments\", priority: 4) { id identifier title priority success } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "mutation { issueUpdate(input: { id: \"i-sec-payments\", priority: 4 }) { issue { id identifier title priority } success } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "mutation { issueUpdate(id: \"i-sec-payments\", input: { priority: 4 }) { issue { id identifier title priority } success } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "mutation { issueUpdate(id: \"i-sec-payments-sm0-v\", input: { priority: 4 }) { issue { id identifier title priority } success } }"
}'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d '{
  "query": "mutation { issueUpdate(id: \"i-sec-payments-sm1-v\", input: { priority: 4 }) { issue { id identifier title priority } success } }"
}'
